    48→/// Validate a batch of `DataColumnSidecar`.
    49→pub fn validate_data_columns<'a, E: EthSpec, I>(
    50→    kzg: &Kzg,
    51→    data_column_iter: I,
    52→) -> Result<(), (Option<u64>, KzgError)>
    53→where
    54→    I: Iterator<Item = &'a Arc<DataColumnSidecar<E>>> + Clone,
    55→{
    56→    let mut cells = Vec::new();
    57→    let mut proofs = Vec::new();
    58→    let mut column_indices = Vec::new();
    59→    let mut commitments = Vec::new();
    60→
    61→    for data_column in data_column_iter {
    62→        let col_index = data_column.index;
    63→
    64→        if data_column.column.is_empty() {
    65→            return Err((Some(col_index), KzgError::KzgVerificationFailed));
    66→        }
    67→
    68→        for cell in &data_column.column {
    69→            cells.push(ssz_cell_to_crypto_cell::<E>(cell).map_err(|e| (Some(col_index), e))?);
    70→            column_indices.push(col_index);
